import{_ as e,o as d,c as r,a2 as o}from"./chunks/framework.C0pL2NcE.js";const g=JSON.parse('{"title":"6. Levels","description":"","frontmatter":{},"headers":[],"relativePath":"gdd/levels.md","filePath":"gdd/levels.md"}'),l={name:"gdd/levels.md"};function s(a,t,n,i,c,h){return d(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="_6-levels" tabindex="-1">6. Levels <a class="header-anchor" href="#_6-levels" aria-label="Permalink to &quot;6. Levels&quot;">​</a></h1><p>Sixteen pictures of 136 × 128-grain frames (grains of about 6 px); the game plays them from <code>src/game/level-edits.json</code> in the order below, named <code>level_1</code> to <code>level_16</code> in the game and in the Level Editor, whatever name a saved or imported copy carries (<code>GAME_ORDER</code> in <code>src/game/levels.ts</code>).</p><ul><li><strong>The game has 16 levels</strong> (<code>GAME_ORDER</code> in <code>src/game/levels.ts</code>), in the order of colony-flow-levels (15).json: the cherries; four full-frame scenes with zoomed grains (levels 2–5); then full-frame scenes (levels 6–15). The small one-subject pictures (<code>builtin-1</code>, <code>builtin-16</code> to <code>builtin-19</code>: ice cream, chick, clownfish, octopus, ladybug) are no longer in the game; a browser&#39;s Level Bank keeps its own copies. Levels with ids <code>builtin-10</code> to <code>builtin-19</code> exist only in <code>level-edits.json</code>.</li></ul><p>The game builds every level&#39;s nests (the hand-set ones were dropped when the grains grew, since the pictures&#39; blocks changed; make new ones with <strong>Tự sinh tổ kiến</strong>). Difficulty rises through picture size, number of colours and nest size (<code>chunk</code>, in blocks before the ×2 nest scale). Not yet checked with the test bot.</p><table tabindex="0"><thead><tr><th>#</th><th>Subject</th><th>Grains</th><th>Blocks</th><th>Colours</th><th>Chunk</th><th>Nests</th><th>Grain zoom</th></tr></thead><tbody><tr><td>1</td><td>Cherries</td><td>3,602</td><td>57</td><td>red, black, olivegreen</td><td>3–5</td><td>rows (3 columns), hand-set</td><td>—</td></tr><tr><td>2</td><td>Rocket</td><td>6,673</td><td>106</td><td>darkblue, white, red</td><td>3–5</td><td>rows</td><td>×1.51</td></tr><tr><td>3</td><td>Cat</td><td>7,564</td><td>119</td><td>white, darkblue, yellow</td><td>3–5</td><td>rows</td><td>×1.41</td></tr><tr><td>4</td><td>Castle</td><td>8,243</td><td>130</td><td>white, skyblue, yellow</td><td>3–5</td><td>rows</td><td>×1.41</td></tr><tr><td>5</td><td>Sailboat</td><td>9,392</td><td>148</td><td>teal, white, yellow</td><td>4–6</td><td>rows</td><td>×1.25</td></tr><tr><td>6</td><td>Dog</td><td>17,404</td><td>274</td><td>pink, orange, black, white, red</td><td>4–6</td><td>rows, hand-set</td><td>—</td></tr><tr><td>7</td><td>Rocket</td><td>16,997</td><td>268</td><td>navy, white, lightyellow, red</td><td>4–6</td><td>rows</td><td>—</td></tr><tr><td>8</td><td>Sleeping cat with flowers</td><td>16,998</td><td>268</td><td>olivegreen, white, yellowgreen, yellow</td><td>4–6</td><td>rows, seed 5</td><td>—</td></tr><tr><td>9</td><td>Sea turtle</td><td>16,998</td><td>268</td><td>navy, cyan, white, red</td><td>4–6</td><td>rows</td><td>—</td></tr><tr><td>10</td><td>Palm tree and sandcastle</td><td>17,404</td><td>275</td><td>darkblue, yellow, green, orangered, teal, red</td><td>3–5</td><td>rows, hand-set</td><td>—</td></tr><tr><td>11</td><td>Sailboat</td><td>16,998</td><td>267</td><td>cyan, white, navy, orangered</td><td>4–6</td><td>rows, seed 3</td><td>—</td></tr><tr><td>12</td><td>Panda</td><td>16,998</td><td>267</td><td>olivegreen, yellowgreen, white, yellow</td><td>4–6</td><td>rows</td><td>—</td></tr><tr><td>13</td><td>Cottage with garden</td><td>16,998</td><td>268</td><td>white, pink, olivegreen, black</td><td>4–7</td><td>rows</td><td>—</td></tr><tr><td>14</td><td>Toucan</td><td>16,998</td><td>269</td><td>yellowgreen, lightorange, cyan, navy, lightyellow</td><td>5–8</td><td>rows, seed 6</td><td>—</td></tr><tr><td>15</td><td>Black cat peeking</td><td>16,998</td><td>268</td><td>yellow, cyan, black, white, olivegreen, yellowgreen</td><td>5–8</td><td>onion</td><td>—</td></tr><tr><td>16</td><td>Jack-o&#39;-lantern pumpkin</td><td>10,000</td><td>157</td><td>navy, orangered, green</td><td>4–6</td><td>rows</td><td>×1.31</td></tr></tbody></table><h2 id="design-rules" tabindex="-1">Design rules <a class="header-anchor" href="#design-rules" aria-label="Permalink to &quot;Design rules&quot;">​</a></h2><p>The full rules for drawing, colouring and building levels are in <a href="./level-design">5. Level design rules</a>.</p><ul><li><p><strong>One area per colour:</strong> keep each colour in one area of the picture. A colour that runs from top to bottom (for example one body colour around the whole picture) makes nests that cannot fill until the very end, and the conveyor overflows.</p></li><li><p><strong>Make and check levels in the Level Editor:</strong> it turns an image into a sand picture in the game&#39;s colours and builds nests that a recorded play wins (see the <a href="./../guide/level-editor">Level Editor guide</a>).</p></li></ul>',8)])])}const w=e(l,[["render",s]]);export{g as __pageData,w as default};
